        // ValidateScript.HandleCommand assigns this exact ScriptDiagnostic array
        // only when IncludeDiagnostics=true, for both valid and invalid source.
        static void AddConditionalValidationDiagnostics(JObject schema)
        {
            if (schema["properties"] is JObject properties &&
                properties["warnings"] != null && properties["errors"] != null &&
                properties["summary"] != null && properties["pathResolution"] != null)
            {
                properties["diagnostics"] = Arr(Obj(
                    ("line", Type("integer")), ("col", Type("integer")),
                    ("severity", Nullable(Type("string"))),
                    ("message", Nullable(Type("string")))));
            }
            foreach (var child in schema.Properties())
            {
                if (child.Value is JObject obj) AddConditionalValidationDiagnostics(obj);
                else if (child.Value is JArray array)
                    foreach (var item in array)
                        if (item is JObject nested) AddConditionalValidationDiagnostics(nested);
            }
        }
